"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class LRUCache:
    def __init__(self, capacity):
        self.given_capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key):
        if (key not in self.cache):
            return (-1)
            # or NULL
            # Move key to front of order (most recently used)
        self.order.remove(key)
        self.order.insert(0, key)
        return self.cache[key]

    def put(self, key, value):
        if (key in self.cache):
            # Update value and move key to front
            self.cache[key] = value
            self.order.remove(key)
            self.order.insert(0, key)
        else:
            if (len(self.order) >= self.given_capacity):
                # Evict the least recently used (last element in order)
                lruKey = self.order[(-1)]
                self.order.pop()
                self.cache.pop(lruKey)
            self.order.insert(0, key)
            self.cache[key] = value
